import{_ as o,o as t,c as n,ag as a}from"./chunks/framework.B7PviQjB.js";const i="/docs/images/collaborate/comments-doc-panel.png",r="/docs/images/collaborate/comments-mention.png",u=JSON.parse('{"title":"Comment and mention people","description":"Comment on cells, text, board items, and PDFs, mention teammates with @, and follow up from the notifications bell.","frontmatter":{"title":"Comment and mention people","description":"Comment on cells, text, board items, and PDFs, mention teammates with @, and follow up from the notifications bell.","type":"how-to"},"headers":[],"relativePath":"collaborate/comments.md","filePath":"collaborate/comments.md"}'),l={name:"collaborate/comments.md"};function s(c,e,m,d,h,p){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="comment-and-mention-people" tabindex="-1">Comment and mention people <a class="header-anchor" href="#comment-and-mention-people" aria-label="Permalink to &quot;Comment and mention people&quot;">​</a></h1><p>Leave feedback on part of a document without changing it, and use <code>@</code> to bring a teammate into the discussion.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Comments work in sheets, docs, boards, and PDFs. Presentations and notes don&#39;t have comments.</li><li>To comment, sign in and have edit access: a workspace member, or someone on an editor <a href="/docs/collaborate/share.html">share link</a>. Viewer links can read comments but not add them.</li><li>You can mention only members of the document&#39;s workspace.</li></ul></div><h2 id="comment-on-a-cell" tabindex="-1">Comment on a cell <a class="header-anchor" href="#comment-on-a-cell" aria-label="Permalink to &quot;Comment on a cell&quot;">​</a></h2><ol><li>Open the sheet and select the cell.</li><li>Right-click and select <strong>Insert comment</strong>, or press <code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code>.</li><li>Type your comment and click <strong>Comment</strong>.</li></ol><p>The thread opens when you select the cell again.</p><h2 id="comment-on-text-in-a-doc" tabindex="-1">Comment on text in a doc <a class="header-anchor" href="#comment-on-text-in-a-doc" aria-label="Permalink to &quot;Comment on text in a doc&quot;">​</a></h2><ol><li>Open the doc and select the text you want to discuss.</li><li>Right-click and select <strong>Insert comment</strong>, or press <code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code>.</li><li>Type your comment and click <strong>Comment</strong>.</li></ol><p>The text is highlighted for everyone. Click the highlight to open the thread. A comment needs selected text; with only a blinking cursor, nothing happens.</p><p><img src="'+i+'" alt="Doc with two highlighted comments and the Comments panel open on the Open tab, one thread resolved"></p><h2 id="comment-on-a-board" tabindex="-1">Comment on a board <a class="header-anchor" href="#comment-on-a-board" aria-label="Permalink to &quot;Comment on a board&quot;">​</a></h2><ol><li>Open the board and click <strong>Comment</strong> in the bottom tool dock.</li><li>Click an item or an empty spot to drop a pin.</li><li>Type your comment and click <strong>Comment</strong>.</li></ol><p>To pin a comment to a selected item, press <code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code>. See <a href="/docs/board/facilitate-a-session.html">Facilitate a session</a>.</p><h2 id="comment-on-a-pdf" tabindex="-1">Comment on a PDF <a class="header-anchor" href="#comment-on-a-pdf" aria-label="Permalink to &quot;Comment on a PDF&quot;">​</a></h2><ol><li>Open the PDF and select some text.</li><li>Click the <strong>Comment</strong> button that appears next to the selection.</li><li>Type your comment and click <strong>Comment</strong>.</li></ol><p>For scans and figures, click the <strong>Comment on a region</strong> icon in the header and drag a box over the page instead. See <a href="/docs/files/pdfs.html">PDFs</a>.</p><h2 id="mention-someone" tabindex="-1">Mention someone <a class="header-anchor" href="#mention-someone" aria-label="Permalink to &quot;Mention someone&quot;">​</a></h2><p>Mentions work in comments on sheets, docs, and boards.</p><ol><li>In a comment, type <code>@</code>.</li><li>Keep typing to filter the list of workspace members.</li><li>Press <code>↑</code> or <code>↓</code> to choose a person, then <code>Enter</code> or <code>Tab</code>.</li></ol><p>The mention appears as a blue chip, and that person gets a notification when you post. To post any comment from the keyboard, press <code>⌘+Enter</code> / <code>Ctrl+Enter</code>.</p><p><img src="'+r+'" alt="Comment box with &quot;@ha&quot; typed and the member list suggesting hackerwins"></p><h2 id="reply-resolve-and-reopen-a-thread" tabindex="-1">Reply, resolve, and reopen a thread <a class="header-anchor" href="#reply-resolve-and-reopen-a-thread" aria-label="Permalink to &quot;Reply, resolve, and reopen a thread&quot;">​</a></h2><ul><li><strong>Reply</strong>: open the thread, type in the reply box, and click <strong>Reply</strong>.</li><li><strong>Resolve</strong>: click the check icon (<strong>Resolve</strong>) on the first comment. The thread moves to the <strong>Resolved</strong> tab.</li><li><strong>Reopen</strong>: open the thread from the <strong>Resolved</strong> tab and click the check icon (<strong>Reopen</strong>).</li></ul><h2 id="edit-or-delete-your-comment" tabindex="-1">Edit or delete your comment <a class="header-anchor" href="#edit-or-delete-your-comment" aria-label="Permalink to &quot;Edit or delete your comment&quot;">​</a></h2><ol><li>Hover your comment and click <strong>⋯</strong> (<strong>More actions</strong>).</li><li>Select <strong>Edit</strong>, change the text, and click <strong>Save</strong>. Or select <strong>Delete</strong>.</li></ol><p>You can edit or delete only your own comments. Deleting the first comment in a thread deletes the whole thread.</p><h2 id="browse-all-comments" tabindex="-1">Browse all comments <a class="header-anchor" href="#browse-all-comments" aria-label="Permalink to &quot;Browse all comments&quot;">​</a></h2><ol><li>Click the comments icon (<strong>Show comments</strong>) in the header. In sheets and docs you can also press <code>⌘+Option+Shift+M</code> / <code>Ctrl+Alt+Shift+M</code>.</li><li>Choose the <strong>Open</strong> or <strong>Resolved</strong> tab.</li><li>Click a thread to jump to its cell, text, or pin.</li></ol><p>In a doc, if someone deletes the text a comment was on, the thread moves to <strong>Orphaned</strong> on the <strong>Open</strong> tab so the discussion isn&#39;t lost.</p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p>The comments icon moves into the header&#39;s <strong>⋮</strong> menu (<strong>More</strong>). Tap <strong>⋮</strong>, then <strong>Comments</strong>, to open the panel and read, reply, and resolve.</p><h2 id="get-notified" tabindex="-1">Get notified <a class="header-anchor" href="#get-notified" aria-label="Permalink to &quot;Get notified&quot;">​</a></h2><p>The bell in the header shows how many unread notifications you have, up to <strong>99+</strong>.</p><ol><li>Click the bell.</li><li>Click a notification to open what it&#39;s about. It&#39;s marked as read.</li><li>To clear the badge, click <strong>Mark all read</strong>.</li></ol><p>You&#39;re notified when:</p><ul><li>someone mentions you in a comment</li><li>someone replies to or resolves a thread you commented in</li><li>someone joins a workspace you own, or accepts an invite you created</li><li>a template you published is approved, rejected, removed from the public gallery, or sent back for review</li><li>a template is waiting for review, if your deployment made you a template reviewer</li></ul><p>Starting a thread notifies nobody unless it mentions someone. You&#39;re never notified about your own actions.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>People on a share link can&#39;t be mentioned and have no bell.</li><li>On a board, comments can&#39;t be added through a share link.</li><li>Restoring an older version removes comments added after it. See <a href="/docs/collaborate/version-history.html">Version history</a>.</li><li>Comments aren&#39;t copied when you make a copy or use a template.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/edit-together.html">Edit together</a> to see who is working where.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to invite reviewers.</li><li><a href="/docs/board/facilitate-a-session.html">Facilitate a session</a> for board comments, voting, and stamps.</li><li>Keyboard shortcuts for <a href="/docs/sheets/keyboard-shortcuts.html">Sheets</a> and <a href="/docs/docs-editor/keyboard-shortcuts.html">Docs</a>.</li></ul>',41)])])}const b=o(l,[["render",s]]);export{u as __pageData,b as default};
